import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, sep } from 'node:path';

// Caller supplies its installed Playwright package and an external generated
// WASM directory. No dependency installation or generated bytes live here.
const [moduleRoot, packageDir, engine = 'chromium'] = process.argv.slice(2);
assert(moduleRoot && packageDir, 'usage: node run.mjs PLAYWRIGHT_PACKAGE WASM_DIRECTORY [ENGINE]');
const playwright = createRequire(resolve(moduleRoot, 'package.json'))('playwright');
assert(['chromium','firefox','webkit'].includes(engine));
const root = resolve(packageDir);
const server = createServer(async (req,res) => {
  try {
    const path = resolve(root, '.' + new URL(req.url, 'http://localhost').pathname);
    assert(path.startsWith(root + sep));
    if (path.endsWith('/index.html')) {
      res.setHeader('content-type','text/html'); res.end('<!doctype html><title>IndexedDB fixture</title>'); return;
    }
    if (path.endsWith('/worker.js')) {
      res.setHeader('content-type','text/javascript');
      res.end(`import init, {Fixture} from './fixture.js';
        await init();
        self.onmessage=async()=>{try{const db=await Fixture.open(77,true);await db.write(1,undefined,new Uint8Array([77]));await db.close();const again=await Fixture.open(77,false);const value=await again.read(1);await again.close();self.postMessage({value:Array.from(value)});}catch(error){self.postMessage({error:String(error)});}};
        self.postMessage({ready:true});`); return;
    }
    res.setHeader('content-type',path.endsWith('.wasm') ? 'application/wasm' : 'text/javascript');
    res.end(await readFile(path));
  } catch {res.statusCode=404;res.end();}
});
await new Promise(resolve => server.listen(0,'127.0.0.1',resolve));
let browser;
const deadline=setTimeout(()=>{void browser?.close();},90000);
deadline.unref();
try {
  browser = await playwright[engine].launch({headless:true});
  const page = await browser.newPage();
  page.on('pageerror',error=>console.error('PAGE_ERROR',error.message));
  page.on('console',message=>{if(message.type()==='log')console.log(message.text());});
  await page.goto(`http://127.0.0.1:${server.address().port}/index.html`);
  const result=await page.evaluate(async()=>{
    const {default:init,Fixture}=await import('./fixture.js'); await init();
    console.log('STEP wasm_initialized');
    const events=[];
    const nativeTransaction=IDBDatabase.prototype.transaction;
    IDBDatabase.prototype.transaction=function(...args) {
      const tx=nativeTransaction.apply(this,args);
      tx.addEventListener('complete',()=>events.push('complete'));
      tx.addEventListener('abort',()=>events.push('abort'));
      return tx;
    };
    const same=(a,b)=>{if(JSON.stringify(a)!==JSON.stringify(b))throw Error('assertion mismatch');};
    const rejects=async(fn,code)=>{try{await fn();}catch(error){same(String(error),code);return;}throw Error('expected refusal');};
    const value=async(db,k)=>{const raw=await db.read(k);return raw===undefined ? undefined : Array.from(raw);};
    const tests=[];
    const passed=name=>{tests.push(name);console.log('PASS '+name);};
    try {
      await rejects(()=>Fixture.open(12,false),'missing_namespace');
      console.log('STEP missing_existing_refused');
      const db=await Fixture.open(12,true);
      await rejects(()=>Fixture.open(12,true),'namespace_exists');
      same(await value(db,1),undefined);
      const before=events.length;
      same(await db.write(1,undefined,new Uint8Array([1])),1);
      if(!events.slice(before).includes('complete'))throw Error('no actual completion before return');
      await db.write(2,undefined,new Uint8Array([2]));
      const failedBefore=events.length;
      await rejects(()=>db.atomic_pair(99),'record_conflict');
      if(!events.slice(failedBefore).includes('abort'))throw Error('no actual atomic abort');
      same(await value(db,1),[1]);same(await value(db,2),[2]);
      const nativePut=IDBObjectStore.prototype.put;
      let firstWriteSucceeded=false;
      IDBObjectStore.prototype.put=function(...args) {
        const request=nativePut.apply(this,args);
        if(args[1] instanceof Uint8Array && args[1][0]===1) {
          request.addEventListener('success',()=>{firstWriteSucceeded=true;this.transaction.abort();},{once:true});
        }
        return request;
      };
      try {await rejects(()=>db.atomic_pair(2),'transaction_aborted');}
      finally {IDBObjectStore.prototype.put=nativePut;}
      same(firstWriteSucceeded,true);same(await value(db,1),[1]);same(await value(db,2),[2]);
      passed('actual abort after write-request success never acknowledges commit');
      same(await db.atomic_pair(2),2);same(await value(db,1),[3]);same(await value(db,2),[4]);
      passed('actual completion and all-or-nothing conflict rollback');
      await db.write(3,undefined,new Uint8Array()); same(await value(db,3),[]);
      await db.write(3,new Uint8Array(),undefined);same(await value(db,3),undefined);
      passed('missing versus empty and exact deletion');
      const second=await Fixture.open(12,false);
      const race=await Promise.allSettled([db.write(1,new Uint8Array([3]),new Uint8Array([5])),second.write(1,new Uint8Array([3]),new Uint8Array([6]))]);
      same(race.filter(r=>r.status==='fulfilled').length,1);
      same(race.filter(r=>r.status==='rejected').map(r=>String(r.reason)),['record_conflict']);
      await second.close();passed('independent connections serialize compare/exchange');
      db.abandon_write(9);
      for(let n=0;n<64;n++) db.abandon_close();
      await db.close();
      await rejects(()=>db.read(9),'closed');
      const reopened=await Fixture.open(12,false);same(await value(reopened,9),[9]);
      same(reopened.abandon_reads(33),32);await reopened.close();passed('observer loss, bounded admission and actual close/reopen');
      const isolated=await Fixture.open(13,true);same(await value(isolated,9),undefined);await isolated.close();passed('exact per-namespace isolation');
      const name=n=>'radroots.indexeddb.v1.'+n.toString(16).padStart(2,'0').repeat(32);
      const rawOpen=(n,version,upgrade)=>new Promise((resolve,reject)=>{
        const request=indexedDB.open(name(n),version);
        request.onupgradeneeded=()=>upgrade?.(request.result);
        request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('raw fixture open failed'));
      });
      const foreign=await rawOpen(14,1,db=>db.createObjectStore('records',{autoIncrement:true}));foreign.close();
      await rejects(()=>Fixture.open(14,false),'incompatible_schema');
      const future=await rawOpen(15,2,db=>db.createObjectStore('records'));future.close();
      await rejects(()=>Fixture.open(15,false),'incompatible_schema');passed('foreign key schema and future version refusal');
      const changed=await Fixture.open(16,true);
      const upgraded=await rawOpen(16,2);await rejects(()=>changed.read(1),'closed');upgraded.close();await changed.close();
      passed('version change closes owned connection');
      const corrupt=await Fixture.open(17,true);
      const raw=await rawOpen(17,1);
      await new Promise((resolve,reject)=>{const tx=raw.transaction('records','readwrite');tx.objectStore('records').put('foreign record',new Uint8Array(32).fill(1));tx.oncomplete=resolve;tx.onabort=reject;});
      raw.close();await rejects(()=>corrupt.read(1),'corrupt_record');await corrupt.close();passed('foreign record representation refusal');
      const oversized=await Fixture.open(19,true);
      const largeRaw=await rawOpen(19,1);
      await new Promise((resolve,reject)=>{const tx=largeRaw.transaction('records','readwrite');tx.objectStore('records').put(new Uint8Array(65537),new Uint8Array(32).fill(1));tx.oncomplete=resolve;tx.onabort=reject;});
      largeRaw.close();await rejects(()=>oversized.read(1),'corrupt_record');await oversized.close();passed('stored record bound before Rust byte copying');
      const evicted=await Fixture.open(18,true);
      await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(name(18));request.onsuccess=resolve;request.onerror=reject;});
      await rejects(()=>evicted.read(1),'closed');await evicted.close();
      await rejects(()=>Fixture.open(18,false),'missing_namespace');passed('actual namespace deletion cannot silently recreate');
      const workerResult=await new Promise((resolve,reject)=>{const worker=new Worker('./worker.js',{type:'module'});worker.onmessage=e=>{if(e.data.ready){worker.postMessage('run');return;}worker.terminate();resolve(e.data);};worker.onerror=e=>{worker.terminate();reject(Error(e.message));};});
      same(workerResult,{value:[77]});passed('dedicated worker actual WASM and IndexedDB reopen');
      return {tests,events:events.reduce((all,event)=>(all[event]=(all[event]??0)+1,all),{})};
    } finally {IDBDatabase.prototype.transaction=nativeTransaction;}
  });
  console.log(JSON.stringify({engine,version:browser.version(),...result}));
} finally {
  clearTimeout(deadline);
  await browser?.close();await new Promise(resolve=>server.close(resolve));
}
